def tint(raw,argb):
 a=(argb>>24)&255;rgb=((argb>>16)&255,(argb>>8)&255,argb&255);out=bytearray(raw)
 for k in range(0,len(raw),4):
  for c in range(3):out[k+c]=round(raw[k+c]*rgb[c]/255)
  out[k+3]=round(raw[k+3]*a/255)
 return bytes(out)
def main():
 e,mapping=trace();a=arrays(RES);p=OUT/'neoui_previews/media_bt';p.mkdir(parents=True,exist_ok=True);data={}
